#include <stdint.h>
#include "stm32f411xe.h"
#include "core_cm4.h"
#include "system_stm32f4xx.h"
#include <stdio.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

static char buffer[150];
char* volatile ptr_TX;

void init(void){

	//CONFIG SYSTEM CLOCK=100MHZ
	RCC->CR |= RCC_CR_HSEON;  // HSE ENABLE
	while(!(RCC->CR & RCC_CR_HSERDY));

	RCC->PLLCFGR &= 0xFFFFFFC0; //LIMPA OS 6BITS DO PLLMx
	RCC->PLLCFGR |= 0x0D;  // SET M=13; fVCO_in = 1.92MHZ

	RCC->PLLCFGR &= 0xFFFF803F; //LIMPA OS 9BITS DO PLLNx
	RCC->PLLCFGR |= 0x1A00 ;    //SET N=104; fVCO_out = 200MHZ

	RCC->PLLCFGR &= 0xFFFCFFFF; // SET P=2; SYSCLK=100MHZ

	RCC->PLLCFGR |= RCC_PLLCFGR_PLLSRC_HSE; // TROCA DE HSI PARA HSE

	RCC->CR |= RCC_CR_PLLON;   // PLL ENABLE
	while(!(RCC->CR & RCC_CR_PLLRDY));

	FLASH->ACR &= ~0x70F;  //LIMPAR OS BITS
	FLASH->ACR |= 0x703; // FLASH COM 3WS PRFTEN ICEN DCEN

	RCC->CFGR &= ~0x03; //LIMPAR OS BITS
	RCC->CFGR |= 0x02; // PLL SELECTED SYSCLK
	while(!(RCC->CFGR & RCC_CFGR_SWS_1));

	RCC->CFGR &= ~0x1C00; //LIMPAR BITS PPRE1
	RCC->CFGR |= 0x1000;  // AHB DIVIDIDO POR 2 f_APB1=50MHZ


	//CONFIG TIMER5_CH1 PA0 (LED 1HZ)
	RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;
	RCC->APB1ENR |= RCC_APB1ENR_TIM5EN;

	GPIOA->MODER &= ~(GPIO_MODER_MODER0);
	GPIOA->MODER |= GPIO_MODER_MODER0_1;
	GPIOA->AFR[0] &= ~(GPIO_AFRL_AFSEL0);
	GPIOA->AFR[0] |= (2 << GPIO_AFRL_AFSEL0_Pos);

	TIM5->PSC = 9999; // 9999 ==> 100MHZ/(9999+1) = 10.0000 CICLOS/S
	TIM5->ARR = 9999; // CONTA ATE 9999 E DA RESET
	TIM5->CCR1 = 5000; // 5000 (DUTY CYCLE) METADE DOS CICLOS A 3.3V OUTRA METADE A 0V

	TIM5->CCMR1 &= ~(TIM_CCMR1_OC1M);
	TIM5->CCMR1 |= (6 << TIM_CCMR1_OC1M_Pos);

	TIM5->CCER |= TIM_CCER_CC1E;
	TIM5->CR1 |= TIM_CR1_CEN;


	//CONFIG ADC
	RCC->APB2ENR |= RCC_APB2ENR_ADC1EN;

	ADC->CCR &= ~(ADC_CCR_ADCPRE);
	ADC->CCR |= (1 << ADC_CCR_ADCPRE_Pos); //PRESCALER ADC 25MHZ

	GPIOA->MODER &= ~(GPIO_MODER_MODER1 | GPIO_MODER_MODER2 | GPIO_MODER_MODER3 | GPIO_MODER_MODER4 | GPIO_MODER_MODER5 );
	GPIOA->MODER |= (GPIO_MODER_MODER1 | GPIO_MODER_MODER2 | GPIO_MODER_MODER3 | GPIO_MODER_MODER4 | GPIO_MODER_MODER5 );

	ADC1->CR2 |= ADC_CR2_ADON;


	//CONFIG USART
	RCC->APB2ENR |= RCC_APB2ENR_USART1EN;
	GPIOA->MODER &= ~(GPIO_MODER_MODER9 | GPIO_MODER_MODER10);
	GPIOA->MODER |= (GPIO_MODER_MODER9_1 | GPIO_MODER_MODER10_1);
	GPIOA->AFR[1] &= ~(GPIO_AFRH_AFSEL9 | GPIO_AFRH_AFSEL10);
	GPIOA->AFR[1] |= ((7 << GPIO_AFRH_AFSEL9_Pos) | (7 << GPIO_AFRH_AFSEL10_Pos));

	USART1->BRR |= 0x364; //MANTISSA=54	FRACTION=4 fCLK=100MHZ BAUDRATE=115200bps
	USART1->CR1 |= (USART_CR1_UE | USART_CR1_TE | USART_CR1_RE );
	NVIC_EnableIRQ(USART1_IRQn);  // LIGAR O SINAL DO INTERRUPT AO CPU
}

uint16_t lerADC(uint32_t canal){
	ADC1->SQR3 &= ~(ADC_SQR3_SQ1);
	ADC1->SQR3 |= canal;

	ADC1->CR2 |= ADC_CR2_SWSTART;
	while(!(ADC1->SR & ADC_SR_EOC));
	return ADC1->DR;
}

void USART1_IRQHandler(void){
	if(USART1->SR & USART_SR_TXE){
		if(*ptr_TX != '\0'){
			USART1->DR = *ptr_TX;
			ptr_TX++;
		} else {
			USART1->CR1 &= ~USART_CR1_TXEIE;
		}
	}
}

int main(void)
{
	init();

	while(1){
		if((USART1->CR1 & USART_CR1_TXEIE)==0){
			snprintf(buffer,sizeof(buffer),"\033[HSensor_IR_1:%-4u\r\nSensor_IR_2:%-4u\r\nSensor_IR_3:%-4u\r\nSensor_IR_4:%-4u\r\nSensor_IR_5:%-4u\r\n ",lerADC(1),lerADC(2),lerADC(3),lerADC(4),lerADC(5));
			ptr_TX = buffer;
			USART1->CR1 |= USART_CR1_TXEIE;
		}
	}

}
